function freshDb(): Connection { return new Connection(new PDO('sqlite::memory:', null, null, [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION])); }
function commerce(): array { $db=freshDb(); $o=new OrderService($db);$o->ensureTables();$i=new InvoiceService($db,null,null,$o);$i->ensureTables();$p=new PaymentService($db,$i,$o);$p->ensureTables();return [$db,$i,$p]; }
function probe(string $id, callable $fn): void { try {$r=$fn();echo json_encode(['id'=>$id,'result'=>$r],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).PHP_EOL;}catch(Throwable $e){echo json_encode(['id'=>$id,'exception'=>get_class($e),'message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE).PHP_EOL;} }
