probe('R13-update-counts-without-running',function(){ $work=__DIR__.'/probe-data/update';if(!is_dir($work.'/files'))mkdir($work.'/files',0755,true);if(!is_dir($work.'/target'))mkdir($work.'/target',0755,true);$db=freshDb();$kp=Coleza\Domain\Updater\PackageSignatureVerifier::generateKeyPair();$manifest=new Coleza\Domain\Updater\UpdatePackageManifest('1.0.1','1.0.0','synthetic',[],[],['CREATE TABLE synthetic_migration (id INT)']);$json=json_encode($manifest->toArray());file_put_contents($work.'/manifest.json',$json);file_put_contents($work.'/manifest.sig',Coleza\Domain\Updater\PackageSignatureVerifier::signPayload($json,$kp['private']));$up=new Coleza\Domain\Updater\StagedUpdateService(new Coleza\Domain\Updater\PackageSignatureVerifier($kp['public']),new Coleza\Domain\Updater\ModuleCompatibilityChecker($db),'1.0.0',$db);$r=$up->applyValidatedUpdate($work,$work.'/target',false);return ['update_result'=>$r,'migration_table_exists'=>$db->selectOne("SELECT name FROM sqlite_master WHERE name='synthetic_migration'")!==null]; });
